export interface GraphNode {
  id: string
  label: string
  /** 'track' | 'chapter' | 'concept' */
  kind: 'track' | 'chapter' | 'concept'
  /** one-sentence essence */
  blurb: string
  /** site link ('' if pure concept — link its chapter instead) */
  link: string
  /** track slug for cluster coloring: fundamentals|pipelines|sql|python|spark|streaming|system-design|cloud|dataops|intuitions|interview|core */
  track: string
  /** 0-2 sample Q&A shown in the detail card */
  qa?: { q: string; a: string }[]
}

export interface GraphEdge {
  source: string
  target: string
  /** relation label shown on hover: 'contains' | 'depends on' | 'related' | 'part of' */
  rel: 'contains' | 'depends on' | 'related' | 'part of'
}

